def url(slug): return '/'+slug+'/'
def icon(name='arrow'):
 paths={'arrow':'M5 12h14M13 6l6 6-6 6','grid':'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z','shield':'M12 3 21 7v5c0 5-9 9-9 9S3 17 3 12V7zM8 12l3 3 5-6','paint':'M4 4h13v7H4zM17 7h4v8h-9v6','robot':'M7 20h10M12 20v-5M7 15l5-6 6 3M5 7l7 2 4-5M5 7V3M3 3h4M16 4l4 2','chart':'M3 3v18h18M7 15l4-4 4 2 6-8','search':'M20 20l-5-5M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0','menu':'M4 6h16M4 12h16M4 18h16','close':'M5 5l14 14M19 5 5 19','cloud':'M7 18h10a5 5 0 0 0 0-10 6 6 0 0 0-11-1 5 5 0 0 0 1 11','people':'M15 21v-3c0-5-12-5-12 0v3M15 8a4 4 0 1 1-8 0 4 4 0 0 1 8 0M17 14c4 0 5 2 5 5','check':'M4 12l5 5L20 6','plus':'M12 4v16M4 12h16'}
 return f'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+f'<path d="{paths.get(name,paths["arrow"])}"/></svg>'
def brand(): return '<a class="brand official-brand" href="/" aria-label="NGETU Distributors & Integrated Solutions home"><img src="/assets/ngetu-logo.png" width="5357" height="3882" alt="NGETU Distributors & Integrated Solutions"></a>'

def link(slug,label=None,cls='text-link'): return f'<a class="{cls}" href="{url(slug)}">{e(label or PAGES[slug]["title"])}{icon()}</a>'
def review(label='Book a free review',interest='',cls='btn'):
 key=next((s for s,p in PAGES.items() if p['title']==interest),interest)
 return ux.review(label,key,cls)

def header(active=''):
 nav=[('sagola-shop','Sagola shop'),('automotive','Automotive'),('business-technology','Business technology'),('industries','Industries'),('about','About')]
 return '<a class="skip" href="#main">Skip to content</a><div class="utility"><div class="wrap"><span><i class="status-dot"></i> SOUTH AFRICAN ROOTS. CONNECTED THINKING.</span><a href="tel:+27796498368">Call Kenneth · +27 79 649 8368 '+icon()+'</a></div></div><header class="site-header"><div class="wrap nav-row">'+brand()+'<nav class="desktop-nav" aria-label="Main navigation">'+''.join(f'<a {"aria-current=page" if s==active else ""} href="/{s}/">{t}</a>' for s,t in nav)+'</nav><button class="icon-btn search-open" aria-label="Search the site">'+icon('search')+'</button>'+review('Free business review',cls='btn nav-cta')+'<button id="menu-toggle" class="icon-btn" aria-controls="mobile-nav" aria-expanded="false" aria-label="Open menu">'+icon('menu')+'</button></div><nav id="mobile-nav" hidden aria-label="Mobile navigation">'+''.join(f'<a href="/{s}/">{t}</a>' for s,t in nav)+link('partners')+link('insights')+review()+'</nav></header>'
def footer():return '''<footer class="site-footer"><div class="wrap footer-top">'''+brand()+'''<p>From the spray gun<br>to the boardroom.</p><div><span class="eyebrow">Explore</span><a href="/sagola-shop/">Sagola shop</a><a href="/automotive/">Automotive</a><a href="/business-technology/">Business technology</a><a href="/training/">Painter training</a></div><div><span class="eyebrow">NGETU</span><a href="/about/">Our story</a><a href="/kenneth/">Meet Kenneth</a><a href="/partners/">Partners & approvals</a><a href="/insights/">Insights</a><a href="/contact/">Contact & enquiries</a><a href="tel:+27796498368">+27 79 649 8368</a><a href="mailto:kenneth@ngetu.co.za">kenneth@ngetu.co.za</a></div></div><div class="wrap footer-bottom"><span>© 2026 NGETU Distributors & Integrated Solutions · Johannesburg, South Africa</span><div><a href="/privacy/">Privacy & POPIA</a><a href="/cookies/">Cookies</a><a href="/terms/">Terms & trademarks</a><a href="/accessibility/">Accessibility</a><a href="/security-terms/">Security</a><button class="text-button" data-consent-open>Measurement preferences</button><a href="/admin/">Site management</a></div></div><div class="wrap review-note">Review edition · Product availability and partner/service terms remain subject to confirmation. The enquiry screen explains the current delivery mode.</div></footer><div class="mobile-bar"><span data-contact-actions><a href="tel:+27796498368">Call Kenneth</a></span><a href="/contact/">Contact Kenneth</a>'''+review('Free business review')+'''</div><dialog id="search-dialog" aria-labelledby="search-title"><div class="dialog-top"><h2 id="search-title">What can we help you find?</h2><button class="icon-btn dialog-close" aria-label="Close search">'''+icon('close')+'''</button></div><label for="site-search" class="sr-only">Search solutions and insights</label><div class="search-input">'''+icon('search')+'''<input id="site-search" type="search" placeholder="Try spray guns, training or Microsoft…" autocomplete="off"></div><p class="search-hint" id="search-count" role="status">Explore solutions, industries and useful insights.</p><div id="search-results"></div></dialog>'''
def shell(title,desc,body,active=''):
 return '<!doctype html><html lang="en-ZA"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+e(title)+' | NGETU</title><meta name="description" content="'+e(desc)+'"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#0b1716"><link rel="icon" type="image/png" href="/assets/ngetu-logo.png"><link rel="stylesheet" href="/styles.css"><link rel="stylesheet" href="/experience.css"><script src="/app.js" defer></script><script src="/experience.js" defer></script></head><body>'+header(active)+'<main id="main">'+body+'</main>'+footer()+'</body></html>'
def cta():return '<section class="closing"><div class="wrap closing-inner"><div><span class="eyebrow">The first step is a conversation</span><h2>Technology changes.<br>Business is still personal.</h2><p>Let’s understand your operation—and what could work better.</p></div>'+review()+'</div></section>'
def cards(slugs):return ux.cards(slugs,PAGES)

home=(ROOT/'homepage.html').read_text()
