for slug,p in PAGES.items():
 body=ux.hero(slug,p)+ux.extras(slug,PAGES)
 body+='<section class="section detail-section"><div class="wrap detail-layout"><aside><span class="eyebrow">In this section</span>'+''.join('<a href="#detail-'+str(i)+'">'+e(b[0])+'</a>' for i,b in enumerate(p['blocks']))+review('Prepare your enquiry',p['title'],'text-link')+'</aside><div class="detail-copy">'
 body+='<!--cms:blocks-->'
 for i,(title,desc,items) in enumerate(p['blocks']):
  body+='<article id="detail-'+str(i)+'"><span class="section-index">0'+str(i+1)+'</span><h2>'+e(title)+'</h2><p>'+e(desc)+'</p>'
  if items:body+='<ul class="check-list">'+''.join('<li>'+icon('check')+'<span>'+e(x)+'</span></li>' for x in items)+'</ul>'
  body+='</article>'
 body+='<!--/cms:blocks-->'
 if p['note']:body+='<div class="scope-note"><strong>Scope & availability</strong><p>'+e(p['note'])+'</p></div>'
 body+='</div></div></section>'
 if p['related'] and slug!='insights':body+='<section class="section related"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Keep the whole business in view</span><h2>'+('Explore the guides.' if slug=='insights' else 'Connected possibilities.')+'</h2></div></div>'+cards(p['related'])+'</div></section>'
 if slug not in ['privacy','cookies','terms','accessibility','security-terms']:body+=cta()
 (OUT/slug).mkdir(exist_ok=True)
 (OUT/slug/'index.html').write_text(shell(p['title'],p['description'],body,slug))

